/* 
    SASS Mixins
*/
/*********************
 RESPONSIVE BREAKPOINTS
*********************/
restricted-access-dialog {
  position: fixed;
  top: 0px;
  left: 0px;
  right: 0px;
  bottom: 0px;
  z-index: 9999;
  /* ANIMATION */ }
  restricted-access-dialog > div.backdrop {
    opacity: 0.9;
    background-color: #000;
    height: 100%;
    width: 100%; }
  restricted-access-dialog > div.login-box {
    position: fixed;
    top: 27%;
    bottom: 27%;
    right: 20%;
    left: 20%;
    width: auto;
    height: auto;
    display: -webkit-box;
    display: -webkit-flex;
    display: -moz-flex;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: center;
    -ms-flex-pack: center;
    -webkit-justify-content: center;
    -moz-justify-content: center;
    justify-content: center;
    -webkit-box-direction: normal;
    -webkit-box-orient: vertical;
    -webkit-flex-direction: column;
    -moz-flex-direction: column;
    -ms-flex-direction: column;
    flex-direction: column;
    padding: 24px;
    color: #fff; }
    restricted-access-dialog > div.login-box > md-icon.close {
      position: absolute;
      right: 16px;
      top: 16px;
      height: 40px;
      width: 40px; }
    restricted-access-dialog > div.login-box > div.logo {
      padding-bottom: 16px;
      text-align: center; }
      restricted-access-dialog > div.login-box > div.logo > md-icon {
        height: 5em;
        width: auto; }
    restricted-access-dialog > div.login-box > div.text {
      font-size: 1.2em;
      text-align: center; }
    restricted-access-dialog > div.login-box > div.legend {
      font-size: 1em;
      font-style: italic;
      text-align: center;
      padding-top: 2em; }
  restricted-access-dialog.ng-show-add {
    animation: 0.4s fadeOut linear; }
  restricted-access-dialog.ng-hide {
    animation: 0.45s fadeIn linear; }

@media (max-width: 800px) {
  restricted-access-dialog > div.login-box {
    position: fixed;
    top: 20%;
    bottom: 20%;
    right: 6%;
    left: 6%; } }

